-- MWT complete schema: 001 to 017 in one file. Generated by joining the numbered scripts.
-- For a fresh database only. Do not run it together with the numbered scripts.

-- ===== 001_genres.sql =====
-- Run once in pgAdmin (Query Tool) on the mwt_dev database.
-- Genres are referenced by users, resources, videos and classifications.
CREATE TABLE IF NOT EXISTS genres (
  id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  color_code TEXT,
  icon_url TEXT,
  description TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ===== 002_teachers.sql =====
-- Run once in pgAdmin (Query Tool) on the mwt_dev database.
CREATE TABLE IF NOT EXISTS teachers (
  id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE,
  profile_image_url TEXT,
  bio TEXT,
  specialty TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ===== 003_users.sql =====
-- Run once in pgAdmin (Query Tool) on the mwt_dev database.
-- Requires 001_genres.sql. cognito_id links the row to the AWS Cognito account.
CREATE TABLE IF NOT EXISTS users (
  id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  cognito_id TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  surname TEXT,
  email TEXT NOT NULL UNIQUE,
  role TEXT NOT NULL DEFAULT 'student',
  level TEXT,
  instrument TEXT,
  genre_id INTEGER REFERENCES genres (id) ON DELETE SET NULL,
  phone_code TEXT,
  phone_number TEXT,
  company TEXT,
  stage TEXT,
  questionnaire_completed BOOLEAN NOT NULL DEFAULT FALSE,
  questionnaire_completed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ===== 004_sessions.sql =====
-- Run once in pgAdmin (Query Tool) on the mwt_dev database.
-- Requires 002_teachers.sql. Live sessions given by a teacher.
CREATE TABLE IF NOT EXISTS sessions (
  id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  title TEXT NOT NULL,
  description TEXT,
  teacher_id INTEGER NOT NULL REFERENCES teachers (id),
  max_students INTEGER NOT NULL CHECK (max_students >= 1),
  min_students INTEGER NOT NULL DEFAULT 1 CHECK (min_students >= 1),
  current_students INTEGER NOT NULL DEFAULT 0 CHECK (current_students >= 0),
  status TEXT NOT NULL DEFAULT 'scheduled',
  session_type TEXT,
  level INTEGER,
  scheduled_date TIMESTAMPTZ NOT NULL,
  meeting_link TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CHECK (min_students <= max_students)
);

-- ===== 005_resources.sql =====
-- Run once in pgAdmin (Query Tool) on the mwt_dev database. Requires 001_genres.sql.
-- Learning resources (documents, sheet music...) that users can open.
CREATE TABLE IF NOT EXISTS resources (
  id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  title TEXT NOT NULL,
  description TEXT,
  file_url TEXT NOT NULL,
  thumbnail_url TEXT,
  file_size_bytes BIGINT CHECK (file_size_bytes >= 0),
  file_type TEXT,
  difficulty_level TEXT,
  genre_id INTEGER REFERENCES genres (id) ON DELETE SET NULL,
  instrument TEXT,
  attachments JSONB NOT NULL DEFAULT '[]'::jsonb,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ===== 006_videos.sql =====
-- Run once in pgAdmin (Query Tool) on the mwt_dev database. Requires 001_genres.sql.
CREATE TABLE IF NOT EXISTS videos (
  id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  title TEXT NOT NULL,
  description TEXT,
  video_url TEXT NOT NULL,
  thumbnail_url TEXT,
  duration_minutes INTEGER CHECK (duration_minutes >= 0),
  difficulty_level TEXT,
  genre_id INTEGER REFERENCES genres (id) ON DELETE SET NULL,
  instrument TEXT,
  sort_order INTEGER NOT NULL DEFAULT 0,
  attachments_count INTEGER NOT NULL DEFAULT 0 CHECK (attachments_count >= 0),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ===== 007_session_enrollments.sql =====
-- Run once in pgAdmin (Query Tool) on the mwt_dev database.
-- Requires 003_users.sql and 004_sessions.sql. A user signing up for a live session.
CREATE TABLE IF NOT EXISTS session_enrollments (
  id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  session_id INTEGER NOT NULL REFERENCES sessions (id) ON DELETE CASCADE,
  enrollment_number INTEGER,
  enrolled_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  unenrolled_at TIMESTAMPTZ,
  status TEXT NOT NULL DEFAULT 'enrolled',
  attendance_status TEXT,
  feedback_rating INTEGER CHECK (feedback_rating BETWEEN 1 AND 5),
  feedback_comments TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS session_enrollments_user_id_idx ON session_enrollments (user_id);
CREATE INDEX IF NOT EXISTS session_enrollments_session_id_idx ON session_enrollments (session_id);

-- ===== 008_user_sessions.sql =====
-- Run once in pgAdmin (Query Tool) on the mwt_dev database.
-- Requires 003_users.sql and 004_sessions.sql. Files a user uploads for a session.
CREATE TABLE IF NOT EXISTS user_sessions (
  id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  session_id INTEGER NOT NULL REFERENCES sessions (id) ON DELETE CASCADE,
  user_id INTEGER NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  file_url TEXT,
  file_type TEXT,
  file_size_bytes BIGINT CHECK (file_size_bytes >= 0),
  upload_status TEXT NOT NULL DEFAULT 'pending',
  activity_type TEXT,
  original_filename TEXT,
  mime_type TEXT,
  duration_seconds INTEGER CHECK (duration_seconds >= 0),
  description TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS user_sessions_user_id_idx ON user_sessions (user_id);
CREATE INDEX IF NOT EXISTS user_sessions_session_id_idx ON user_sessions (session_id);

-- ===== 009_resource_progress.sql =====
-- Run once in pgAdmin (Query Tool) on the mwt_dev database.
-- Requires 003_users.sql and 005_resources.sql. One row per user and resource.
CREATE TABLE IF NOT EXISTS resource_progress (
  id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  resource_id INTEGER NOT NULL REFERENCES resources (id) ON DELETE CASCADE,
  is_viewed BOOLEAN NOT NULL DEFAULT FALSE,
  viewed_at TIMESTAMPTZ,
  view_count INTEGER NOT NULL DEFAULT 0 CHECK (view_count >= 0),
  viewed_percentage NUMERIC(5, 2) NOT NULL DEFAULT 0 CHECK (viewed_percentage BETWEEN 0 AND 100),
  viewed_duration_seconds INTEGER NOT NULL DEFAULT 0 CHECK (viewed_duration_seconds >= 0),
  last_position_seconds INTEGER NOT NULL DEFAULT 0 CHECK (last_position_seconds >= 0),
  total_view_time_seconds INTEGER NOT NULL DEFAULT 0 CHECK (total_view_time_seconds >= 0),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (user_id, resource_id)
);

-- ===== 010_video_progress.sql =====
-- Run once in pgAdmin (Query Tool) on the mwt_dev database.
-- Requires 003_users.sql and 006_videos.sql. One row per user and video.
CREATE TABLE IF NOT EXISTS video_progress (
  id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  video_id INTEGER NOT NULL REFERENCES videos (id) ON DELETE CASCADE,
  is_watched BOOLEAN NOT NULL DEFAULT FALSE,
  watched_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (user_id, video_id)
);

-- ===== 011_classifications.sql =====
-- Run once in pgAdmin (Query Tool) on the mwt_dev database.
-- Requires 001_genres.sql and 003_users.sql. Result of a user's level questionnaire.
CREATE TABLE IF NOT EXISTS classifications (
  id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  assigned_level TEXT,
  score INTEGER CHECK (score >= 0),
  max_score INTEGER CHECK (max_score >= 0),
  percentage NUMERIC(5, 2) CHECK (percentage BETWEEN 0 AND 100),
  answers JSONB,
  selected_instrument TEXT,
  selected_genre_id INTEGER REFERENCES genres (id) ON DELETE SET NULL,
  recommendations JSONB,
  classified_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS classifications_user_id_idx ON classifications (user_id);

-- ===== 012_experimental_sessions.sql =====
-- Run once on the mwt_dev database (pgAdmin Query Tool, psql or Docker).
-- No dependencies. Light list of the experimental sessions that exist.
-- Titles, descriptions and texts stay in the front-end.
-- If the old experimental tables exist, run maintenance/drop_old_experimental_tables.sql first.
CREATE TABLE IF NOT EXISTS experimental_sessions (
  id TEXT PRIMARY KEY,
  branches TEXT[] NOT NULL DEFAULT '{}',
  category TEXT,
  active BOOLEAN NOT NULL DEFAULT TRUE
);

-- ===== 013_session_attempts.sql =====
-- Run once on the mwt_dev database (pgAdmin Query Tool, psql or Docker).
-- Requires 003_users.sql and 012_experimental_sessions.sql.
-- One row each time a user does a session. The final feedback lives in the same row
-- (feeling_after and would_repeat stay empty if the user skips the feedback).
CREATE TABLE IF NOT EXISTS session_attempts (
  id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  session_id TEXT NOT NULL REFERENCES experimental_sessions (id) ON DELETE CASCADE,
  started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  finished_at TIMESTAMPTZ,
  completed BOOLEAN NOT NULL DEFAULT FALSE,
  score INTEGER CHECK (score >= 0),
  details JSONB,
  feeling_after TEXT,
  would_repeat BOOLEAN,
  CHECK (finished_at IS NULL OR finished_at >= started_at)
);

CREATE INDEX IF NOT EXISTS session_attempts_user_id_idx ON session_attempts (user_id);
CREATE INDEX IF NOT EXISTS session_attempts_session_id_idx ON session_attempts (session_id);

-- ===== 014_session_questionnaire.sql =====
-- Run once on the mwt_dev database (pgAdmin Query Tool, psql or Docker).
-- Requires 003_users.sql and 012_experimental_sessions.sql.
-- Answers of "Te ayudamos a elegir". Options and words are keys defined in the front-end.
CREATE TABLE IF NOT EXISTS session_questionnaire (
  id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  goal TEXT NOT NULL,
  minutes TEXT CHECK (minutes IN ('quick', 'short', 'long')),
  words TEXT[] NOT NULL DEFAULT '{}' CHECK (cardinality(words) <= 3),
  recommended_session_id TEXT REFERENCES experimental_sessions (id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS session_questionnaire_user_id_idx ON session_questionnaire (user_id);

-- ===== 015_theory_results.sql =====
-- Run once on the mwt_dev database (pgAdmin Query Tool, psql or Docker).
-- Requires 001_genres.sql and 003_users.sql.
-- Latest result of each activity or question, one row per user and item.
-- item_id is the key of the activity or question defined in the front-end.
CREATE TABLE IF NOT EXISTS theory_results (
  user_id INTEGER NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  genre_id INTEGER NOT NULL REFERENCES genres (id) ON DELETE CASCADE,
  item_id TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('activity', 'question')),
  completed BOOLEAN NOT NULL DEFAULT FALSE,
  correct BOOLEAN,
  answer JSONB,
  score INTEGER CHECK (score >= 0),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (user_id, genre_id, item_id)
);

-- ===== 016_theory_progress.sql =====
-- Run once on the mwt_dev database (pgAdmin Query Tool, psql or Docker).
-- Requires 001_genres.sql and 003_users.sql.
-- How far each user has unlocked in each genre. progress looks like 1.1.1.
CREATE TABLE IF NOT EXISTS theory_progress (
  user_id INTEGER NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  genre_id INTEGER NOT NULL REFERENCES genres (id) ON DELETE CASCADE,
  progress TEXT NOT NULL CHECK (progress ~ '^[0-9]+(\.[0-9]+)*$'),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (user_id, genre_id)
);

